// Rolling-window rate limit: blocks a candidate email that submits the form
// more than MAX_SUBMISSIONS times within WINDOW_MINUTES. This runs BEFORE any
// file processing or LLM calls to protect API budget from abuse/spam.
const WINDOW_MINUTES = 10;
const MAX_SUBMISSIONS = 3;

const now = Date.now();
const rows = $input.all().map(item => item.json).filter(r => r && r.submitted_at);
const recentCount = rows.filter(r => (now - new Date(r.submitted_at).getTime()) <= WINDOW_MINUTES * 60000).length;
const rateLimited = recentCount > MAX_SUBMISSIONS;

return [{
  json: {
    rate_limited: rateLimited,
    recent_submission_count: recentCount,
    window_minutes: WINDOW_MINUTES,
    max_submissions: MAX_SUBMISSIONS
  }
}];

const position = $('Job Application Form').first().json['Position Applied For'];
const normalizedPosition = (position || '').toString().trim().toLowerCase();
const allJobs = $input.all();
const match = allJobs.find(item => (item.json.position || '').toString().trim().toLowerCase() === normalizedPosition);
return [{ json: match ? { ...match.json, requirements_found: true } : { position: position, requirements: '', requirements_found: false } }];

