// Compare each candidate slot (in preference order, computed by "Propose Interview Slot")
// against the recruiter's busy events fetched for the whole search window,
// and pick the first candidate slot that has no conflict.
const busyEvents = $input.all()
  .map(item => item.json)
  .filter(e => e && e.start && e.end);

function overlaps(aStart, aEnd, bStart, bEnd) {
  return aStart < bEnd && aEnd > bStart;
}
function eventBounds(e) {
  const s = e.start.dateTime || e.start.date;
  const en = e.end.dateTime || e.end.date;
  return { start: s ? new Date(s) : null, end: en ? new Date(en) : null };
}

function formatAlgiers(isoString) {
  if (!isoString) return null;
  const d = new Date(isoString);
  const datePart = d.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Africa/Algiers' });
  const timePart = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'Africa/Algiers' });
  return `${datePart} at ${timePart} (Algiers time)`;
}

const candidates = $('Propose Interview Slot').item.json.candidate_slots || [];

let chosen = null;
for (const c of candidates) {
  const cStart = new Date(c.slot_start);
  const cEnd = new Date(c.slot_end);
  const conflict = busyEvents.some(e => {
    const b = eventBounds(e);
    if (!b.start || !b.end) return false;
    return overlaps(cStart, cEnd, b.start, b.end);
  });
  if (!conflict) { chosen = c; break; }
}

return [{
  json: {
    slot_found: !!chosen,
    slot_start: chosen ? chosen.slot_start : null,
    slot_end: chosen ? chosen.slot_end : null,
    slot_start_display: chosen ? formatAlgiers(chosen.slot_start) : null,
    candidates_checked: candidates.length,
    busy_event_count: busyEvents.length
  }
}];

// alwaysOutputData on 'Check Existing Applications' guarantees at least one item
// flows through even when zero rows actually match (an empty placeholder {}).
// We must only count items that have real row data (e.g. an email field),
// otherwise every candidate would be wrongly flagged as a duplicate.
const matches = $input.all().filter(item => item.json && Object.keys(item.json).length > 0 && item.json.email);
const original = $('Job Application Form').first();
return [{
  json: { ...original.json, is_duplicate: matches.length > 0, duplicate_match_count: matches.length },
  binary: original.binary
}];

// ---- Scheduling configuration (edit these to change scheduling behavior) ----
const INTERVIEW_DURATION_MINUTES = 30;
const WORKING_HOUR_START = 9;   // 24h format
const WORKING_HOUR_END = 17;    // 24h format
const DEFAULT_START_HOUR = 10;  // preferred interview hour, must be within working hours
const DAYS_AHEAD = 2;           // earliest business day from now to propose
const MAX_CANDIDATE_DAYS = 5;   // how many business days to try, in order, before asking a human to schedule manually
// --------------------------------------------------------------------------

if (DEFAULT_START_HOUR < WORKING_HOUR_START || DEFAULT_START_HOUR + (INTERVIEW_DURATION_MINUTES / 60) > WORKING_HOUR_END) {
  throw new Error('Scheduling config error: DEFAULT_START_HOUR + duration falls outside WORKING_HOUR_START/END. Fix the constants at the top of this node.');
}

function addDays(date, days) {
  const d = new Date(date.getTime());
  d.setDate(d.getDate() + days);
  return d;
}
function isWeekend(d) {
  const day = d.getDay();
  return day === 0 || day === 6;
}

const now = new Date($now.toISO());
const candidates = [];
let cursor = addDays(now, DAYS_AHEAD);
let guard = 0;
while (candidates.length < MAX_CANDIDATE_DAYS && guard < 30) {
  guard++;
  if (!isWeekend(cursor)) {
    const start = new Date(cursor);
    start.setHours(DEFAULT_START_HOUR, 0, 0, 0);
    const end = new Date(start.getTime() + INTERVIEW_DURATION_MINUTES * 60000);
    candidates.push({ slot_start: start.toISOString(), slot_end: end.toISOString() });
  }
  cursor = addDays(cursor, 1);
}

const searchWindowStart = candidates[0].slot_start;
const lastCandidateEnd = new Date(candidates[candidates.length - 1].slot_end);
const searchWindowEnd = new Date(lastCandidateEnd.getTime() + 24 * 60 * 60000).toISOString();

return $input.all().map(item => ({
  json: {
    ...item.json,
    candidate_slots: candidates,
    search_window_start: searchWindowStart,
    search_window_end: searchWindowEnd
  },
  binary: item.binary
}));

// The recruiter's Data Table 'id' column is a real, database-assigned, strictly-increasing
// serial number (assigned atomically by the DB on insert) - it gives every execution that
// raced for this exact slot_start a single, unambiguous, deterministic arrival order.
// Whichever execution's insert got the LOWEST id among still-valid (non-expired) rows wins.

const LOCK_TTL_MINUTES = 5; // stale/crashed executions stop blocking a slot after this long
const myId = $('Reserve Slot Lock').item.json.id;
const now = Date.now();

const rows = $input.all()
  .map(item => item.json)
  .filter(r => r && typeof r.id === 'number' && r.createdAt)
  .filter(r => (now - new Date(r.createdAt).getTime()) <= LOCK_TTL_MINUTES * 60000)
  .sort((a, b) => a.id - b.id);

const winnerId = rows.length > 0 ? rows[0].id : null;
const acquired = winnerId === myId;

return [{
  json: {
    lock_acquired: acquired,
    my_lock_row_id: myId,
    winner_row_id: winnerId,
    competing_locks: rows.length,
    attempted_slot_start: $('Find Next Available Slot').item.json.slot_start,
    attempted_slot_end: $('Find Next Available Slot').item.json.slot_end
  }
}];
